  plumbing: "Plumbing",
  electrical: "Electrical hazard",
  hvac: "Heating / cooling",
  appliance: "Appliance",
  gas: "Gas smell / CO",
  fire: "Fire / smoke",
  sewage: "Sewage backup",
  security: "Security",
  injury: "Injury",
  structural: "Ceiling / structural",
  lockout: "Lockout",
  pest: "Pests",
  mold: "Mold",
  life_safety_device: "Smoke/CO detector",
